<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',-apple-system,BlinkMacSystemFont,sans-serif;background:#000;color:#fff;line-height:1.5;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
button{cursor:pointer;font:inherit;border:none;background:none;color:inherit}
input{font:inherit;color:inherit}

.container{max-width:1200px;margin:0 auto;padding:0 24px}

/* Header */
.header{position:fixed;top:0;left:0;right:0;z-index:100;padding:16px 0;transition:background .3s}
.header.scrolled{background:#000}
.header .container{display:flex;align-items:center;justify-content:space-between}
.logo{font-family:'Bebas Neue',sans-serif;font-size:2rem;color:#E50914;letter-spacing:2px;line-height:1}
.header-right{display:flex;align-items:center;gap:16px}
.lang-select{position:relative}
.lang-select select{appearance:none;-webkit-appearance:none;background:rgba(22,22,22,.7);border:1px solid rgba(255,255,255,.25);color:#fff;padding:6px 36px 6px 16px;border-radius:4px;font-size:.875rem;cursor:pointer}
.lang-select::after{content:'';position:absolute;right:12px;top:50%;transform:translateY(-25%);border:4px solid transparent;border-top-color:#fff;pointer-events:none}
.btn-signin{background:#E50914;color:#fff;padding:7px 18px;border-radius:4px;font-size:.875rem;font-weight:600;transition:background .2s}
.btn-signin:hover{background:#c20812}

/* Hero */
.hero{position:relative;min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;padding:120px 24px 80px;overflow:hidden}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg::before{content:'';position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.95) 0%,rgba(0,0,0,.6) 40%,rgba(0,0,0,.4) 65%,rgba(0,0,0,.7) 100%);z-index:2}
.hero-mosaic{display:grid;grid-template-columns:repeat(6,1fr);grid-template-rows:repeat(3,1fr);gap:4px;width:120%;height:120%;position:absolute;top:-10%;left:-10%;z-index:1;transform:rotate(-5deg) scale(1.1);opacity:.6}
.hero-mosaic-item{background:linear-gradient(135deg,#1a1a2e,#16213e,#0f3460,#533483,#E50914);border-radius:2px}
.hero-content{position:relative;z-index:3;max-width:800px}
.hero-title{font-family:'Bebas Neue',sans-serif;font-size:clamp(2.5rem,6vw,5rem);font-weight:900;line-height:1.1;margin-bottom:16px;letter-spacing:1px}
.hero-subtitle{font-size:clamp(1rem,2vw,1.5rem);font-weight:500;margin-bottom:24px}
.hero-prompt{font-size:1rem;color:#ccc;margin-bottom:16px}
.hero-form{display:flex;gap:8px;max-width:560px;margin:0 auto}
.hero-form input{flex:1;background:rgba(22,22,22,.7);border:1px solid rgba(255,255,255,.3);padding:16px;border-radius:4px;font-size:1rem;color:#fff;outline:none;transition:border .2s}
.hero-form input:focus{border-color:#fff}
.hero-form input::placeholder{color:#999}
.btn-primary{background:#E50914;color:#fff;padding:14px 28px;border-radius:4px;font-size:1.25rem;font-weight:700;white-space:nowrap;display:inline-flex;align-items:center;gap:4px;transition:background .2s}
.btn-primary:hover{background:#c20812}
.hero-scroll{position:absolute;bottom:40px;left:50%;transform:translateX(-50%);z-index:3;animation:bounce 2s infinite}
.hero-scroll span{display:block;width:30px;height:50px;border:2px solid rgba(255,255,255,.3);border-radius:15px;position:relative}
.hero-scroll span::after{content:'';position:absolute;top:8px;left:50%;transform:translateX(-50%);width:4px;height:10px;background:#fff;border-radius:2px;animation:scroll 1.5s infinite}
@keyframes bounce{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(10px)}}
@keyframes scroll{0%{opacity:1;top:8px}100%{opacity:0;top:24px}}

/* Divider */
.divider{height:4px;background:linear-gradient(to right,transparent,#E50914,transparent)}

/* Sections */
.section{padding:80px 0}
.section-title{font-family:'Bebas Neue',sans-serif;font-size:clamp(2rem,4vw,3rem);margin-bottom:32px;letter-spacing:1px}

/* Trending */
.trending-wrapper{position:relative}
.trending-carousel{display:flex;gap:16px;overflow-x:auto;scroll-behavior:smooth;scrollbar-width:none;padding-bottom:8px;-webkit-overflow-scrolling:touch;cursor:grab}
.trending-carousel::-webkit-scrollbar{display:none}
.trending-carousel.dragging{cursor:grabbing;scroll-behavior:auto}
.trending-card{flex:0 0 auto;width:220px;position:relative;border-radius:8px;overflow:hidden;transition:transform .3s}
.trending-card:hover{transform:scale(1.05)}
.trending-rank{position:absolute;left:-8px;bottom:-20px;font-family:'Bebas Neue',sans-serif;font-size:8rem;font-weight:900;color:rgba(0,0,0,.8);-webkit-text-stroke:2px rgba(255,255,255,.3);text-stroke:2px rgba(255,255,255,.3);line-height:1;z-index:2;pointer-events:none;user-select:none}
.trending-poster{width:100%;aspect-ratio:2/3;background:linear-gradient(135deg,#1a1a2e,#533483);display:flex;align-items:flex-end;padding:12px;border-radius:8px;position:relative;overflow:hidden}
.trending-poster::after{content:'';position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.8) 0%,transparent 50%)}
.trending-poster-title{position:relative;z-index:1;font-weight:700;font-size:.875rem}
.carousel-arrow{position:absolute;top:50%;transform:translateY(-50%);z-index:5;width:44px;height:44px;background:rgba(0,0,0,.7);border:1px solid rgba(255,255,255,.2);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.5rem;transition:background .2s}
.carousel-arrow:hover{background:rgba(0,0,0,.9)}
.carousel-arrow.prev{left:-8px}
.carousel-arrow.next{right:-8px}

/* Features */
.features-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.feature-card{background:linear-gradient(145deg,#1a0a2e,#0d1321);border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:28px;position:relative;overflow:hidden;transition:transform .3s,border-color .3s}
.feature-card:hover{transform:translateY(-4px);border-color:rgba(255,255,255,.15)}
.feature-card h3{font-size:1.25rem;font-weight:700;margin-bottom:12px;line-height:1.3}
.feature-card p{color:#b3b3b3;font-size:.95rem;line-height:1.6;margin-bottom:40px}
.feature-icon{position:absolute;bottom:20px;right:20px;font-size:2rem;opacity:.8}

/* FAQ */
.faq-list{max-width:900px;margin:0 auto;display:flex;flex-direction:column;gap:8px}
.faq-item{background:#141414;border:1px solid rgba(255,255,255,.08);border-radius:8px;overflow:hidden;transition:background .2s}
.faq-item:hover{background:#1a1a1a}
.faq-question{width:100%;display:flex;align-items:center;justify-content:space-between;padding:20px 28px;font-size:1.15rem;font-weight:500;text-align:left;transition:background .2s}
.faq-question .icon{font-size:1.75rem;font-weight:300;transition:transform .35s cubic-bezier(.4,0,.2,1);flex-shrink:0;margin-left:16px}
.faq-item.open .faq-question .icon{transform:rotate(45deg)}
.faq-answer{max-height:0;overflow:hidden;transition:max-height .4s cubic-bezier(.4,0,.2,1),padding .4s cubic-bezier(.4,0,.2,1)}
.faq-answer-inner{padding:0 28px 24px;color:#b3b3b3;font-size:1rem;line-height:1.7}
.faq-item.open .faq-answer{max-height:400px}

/* Bottom CTA */
.cta-section{text-align:center;max-width:700px;margin:0 auto}
.cta-section .hero-form{margin-top:20px}

/* Footer */
.footer{padding:60px 0 30px;border-top:1px solid rgba(255,255,255,.08);color:#b3b3b3;font-size:.875rem}
.footer-contact{margin-bottom:28px}
.footer-contact a{text-decoration:underline;text-underline-offset:2px}
.footer-links{display:grid;grid-template-columns:repeat(4,1fr);gap:16px 40px;margin-bottom:28px}
.footer-links ul{list-style:none;display:flex;flex-direction:column;gap:10px}
.footer-links a:hover{text-decoration:underline;text-underline-offset:2px}
.footer-bottom{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-top:28px;padding-top:28px;border-top:1px solid rgba(255,255,255,.08)}

@media (max-width:1024px){
  .features-grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:768px){
  .hero-form{flex-direction:column}
  .btn-primary{justify-content:center}
  .features-grid{grid-template-columns:1fr}
  .footer-links{grid-template-columns:repeat(2,1fr)}
  .trending-card{width:170px}
}
@media (max-width:480px){
  .container{padding:0 16px}
  .section{padding:50px 0}
  .logo{font-size:1.5rem}
  .header .lang-select{display:none}
}
