<script>
(function(){
  /* Fix JSX-style trending cards */
  const carousel = document.getElementById('trendingCarousel');
  const titles = ["Bloodhounds","BEEF","XO, Kitty","War Machine","Bridgerton","Stranger Things","Agent from Above","Boyfriend on Demand","KPop Demon Hunters","Emily in Paris"];
  carousel.innerHTML = titles.map((title,i) =>
    `<div class="trending-card">
      <div class="trending-poster">
        <span class="trending-rank">${i+1}</span>
        <span class="trending-poster-title">${title}</span>
      </div>
    </div>`
  ).join('');

  /* Header scroll effect */
  window.addEventListener('scroll',() => {
    document.getElementById('header').classList.toggle('scrolled', window.scrollY > 50);
  });

  /* FAQ accordion */
  window.toggleFAQ = function(btn) {
    const item = btn.parentElement;
    const isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item.open').forEach(el => {
      el.classList.remove('open');
      el.querySelector('.faq-question').setAttribute('aria-expanded','false');
    });
    if (!isOpen) {
      item.classList.add('open');
      btn.setAttribute('aria-expanded','true');
    }
  };

  /* Carousel scroll */
  window.scrollCarousel = function(dir) {
    carousel.scrollBy({ left: dir * 472, behavior: 'smooth' });
  };

  /* Touch swipe */
  let isDown = false, startX, scrollLeftPos;
  carousel.addEventListener('mousedown',e => {
    isDown = true; carousel.classList.add('dragging');
    startX = e.pageX - carousel.offsetLeft;
    scrollLeftPos = carousel.scrollLeft;
  });
  carousel.addEventListener('mouseleave',() => { isDown = false; carousel.classList.remove('dragging'); });
  carousel.addEventListener('mouseup',() => { isDown = false; carousel.classList.remove('dragging'); });
  carousel.addEventListener('mousemove',e => {
    if (!isDown) return;
    e.preventDefault();
    const x = e.pageX - carousel.offsetLeft;
    carousel.scrollLeft = scrollLeftPos - (x - startX) * 2;
  });
  carousel.addEventListener('touchstart',e => {
    startX = e.touches[0].pageX - carousel.offsetLeft;
    scrollLeftPos = carousel.scrollLeft;
  });
  carousel.addEventListener('touchmove',e => {
    const x = e.touches[0].pageX - carousel.offsetLeft;
    carousel.scrollLeft = scrollLeftPos - (x - startX);
  });

  /* Email form handler */
  window.handleEmailSubmit = function(e,source) {
    e.preventDefault();
    const input = e.target.querySelector('input');
    if (input.checkValidity()) {
      alert('Thanks! In a real app, this would start your subscription.');
    }
  };
})();
</script>

