<script>
(function(){
  /* ── Populate trending carousel ── */
  var titles = ["Bloodhounds","BEEF","XO, Kitty","War Machine","Bridgerton","Stranger Things","Agent from Above","Boyfriend on Demand","KPop Demon Hunters","Emily in Paris"];
  var posters = [
    "linear-gradient(135deg,#1a1a2e,#E50914)",
    "linear-gradient(135deg,#16213e,#533483)",
    "linear-gradient(135deg,#0f3460,#E50914)",
    "linear-gradient(135deg,#1a1a2e,#16213e)",
    "linear-gradient(135deg,#533483,#0f3460)",
    "linear-gradient(135deg,#E50914,#1a1a2e)",
    "linear-gradient(135deg,#16213e,#0f3460)",
    "linear-gradient(135deg,#0f3460,#533483)",
    "linear-gradient(135deg,#533483,#E50914)",
    "linear-gradient(135deg,#1a1a2e,#0f3460)"
  ];
  var carousel = document.getElementById('trendingCarousel');
  carousel.innerHTML = titles.map(function(title,i){
    return '<div class="trending-card">' +
      '<div class="trending-poster" style="background:' + posters[i] + '">' +
        '<span class="trending-rank">' + (i+1) + '</span>' +
        '<span class="trending-poster-title">' + title + '</span>' +
      '</div>' +
    '</div>';
  }).join('');

  /* ── Header scroll ── */
  window.addEventListener('scroll',function(){
    document.getElementById('header').classList.toggle('scrolled', window.scrollY > 50);
  });

  /* ── FAQ accordion ── */
  window.toggleFAQ = function(btn){
    var item = btn.parentElement;
    var isOpen = item.classList.contains('open');
    var allOpen = document.querySelectorAll('.faq-item.open');
