<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Inter',-apple-system,BlinkMacSystemFont,sans-serif;background:#000;color:#fff;line-height:1.5;-webkit-font-smoothing:antialiased;min-height:100vh;display:flex;flex-direction:column}
a{color:inherit;text-decoration:none}
button{cursor:pointer;font:inherit;border:none;background:none;color:inherit}
input{font:inherit;color:inherit}

/* ── Header ── */
.header{padding:24px 32px;display:flex;align-items:center;justify-content:space-between}
.logo{font-family:'Bebas Neue',sans-serif;font-size:2rem;color:#E50914;letter-spacing:2px;line-height:1}

/* ── Login wrapper ── */
.login-wrapper{flex:1;display:flex;align-items:center;justify-content:center;padding:40px 24px 80px}
.login-card{width:100%;max-width:420px}

.login-heading{font-size:2rem;font-weight:700;margin-bottom:8px}
.login-subtext{color:#b3b3b3;font-size:.95rem;margin-bottom:28px}
.login-subtext a{color:#fff;font-weight:600;text-decoration:underline;text-underline-offset:2px}
.login-subtext a:hover{color:#E50914}

.login-form{display:flex;flex-direction:column;gap:16px}
.form-group{display:flex;flex-direction:column;gap:6px}
.form-group label{font-size:.875rem;font-weight:500;color:#ccc}
.form-group input{background:#141414;border:1px solid rgba(255,255,255,.15);padding:14px 16px;border-radius:6px;font-size:1rem;color:#fff;outline:none;transition:border .2s,background .2s}
.form-group input:focus{border-color:#E50914;background:#1a1a1a}
.form-group input::placeholder{color:#666}

.btn-login{background:#E50914;color:#fff;padding:14px;border-radius:6px;font-size:1.1rem;font-weight:700;width:100%;transition:background .2s;margin-top:8px}
.btn-login:hover{background:#c20812}

.login-divider{display:flex;align-items:center;gap:12px;color:#666;font-size:.85rem;margin:24px 0}
.login-divider::before,.login-divider::after{content:'';flex:1;height:1px;background:rgba(255,255,255,.1)}
.login-divider span{flex-shrink:0}

.btn-create-account{display:block;width:100%;padding:14px;border-radius:6px;font-size:1rem;font-weight:600;text-align:center;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.15);color:#fff;transition:background .2s,border-color .2s}
.btn-create-account:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.25)}

/* ── Get Help ── */
.help-section{margin-top:28px;text-align:center}
.help-toggle{font-size:.9rem;color:#b3b3b3;font-weight:500;transition:color .2s;display:inline-flex;align-items:center;gap:6px}
.help-toggle:hover{color:#fff}
.help-toggle .icon{display:inline-block;transition:transform .3s;font-size:.7rem}
.help-section.open .help-toggle .icon{transform:rotate(180deg)}
.help-content{max-height:0;overflow:hidden;transition:max-height .35s cubic-bezier(.4,0,.2,1),margin .35s}
.help-section.open .help-content{max-height:200px;margin-top:16px}
.help-content-inner{background:#141414;border:1px solid rgba(255,255,255,.08);border-radius:8px;padding:20px;text-align:left;font-size:.9rem;color:#b3b3b3;line-height:1.7}
.help-content-inner a{color:#E50914;text-decoration:underline;text-underline-offset:2px}
.help-content-inner a:hover{color:#ff4d4d}

/* ── Footer ── */
.login-footer{padding:24px 32px;text-align:center;color:#666;font-size:.8rem;border-top:1px solid rgba(255,255,255,.05)}
.login-footer a{color:#b3b3b3}
.login-footer a:hover{text-decoration:underline}

/* ── Validation styles ── */
.form-group input:invalid:not(:placeholder-shown){border-color:#E50914}
.form-group .error-msg{font-size:.8rem;color:#E50914;display:none}
.form-group input:invalid:not(:placeholder-shown) ~ .error-msg{display:block}

/* ── Responsive ── */
@media (max-width:480px){
  .header{padding:16px 20px}
  .login-wrapper{padding:24px 20px 60px}
  .login-heading{font-size:1.5rem}
  .login-footer{padding:20px}
}

/* ── Background accent ── */
body::before{content:'';position:fixed;top:-50%;left:-50%;width:200%;height:200%;background:radial-gradient(ellipse at 50% 0%,rgba(229,9,20,.08) 0%,transparent 50%);pointer-events:none;z-index:-1}
</style>
