<body>

<!-- ── Header ── -->
<header class="header">
  <a href="index.html" class="logo">StreamWave</a>
</header>

<!-- ── Login Form ── -->
<main class="login-wrapper">
  <div class="login-card">
    <h1 class="login-heading">Enter your info to sign in</h1>
    <p class="login-subtext">Or <a href="index.html">get started with a new account</a>.</p>

    <form class="login-form" id="loginForm" onsubmit="return handleLogin(event)" novalidate>
      <div class="form-group">
        <label for="email">Email address or mobile number</label>
        <input type="text" id="email" placeholder="Email or mobile number" required>
        <span class="error-msg">Please enter a valid email or mobile number.</span>
      </div>
      <div class="form-group">
        <label for="password">Password</label>
        <input type="password" id="password" placeholder="Password" required minlength="4">
        <span class="error-msg">Password must be at least 4 characters.</span>
      </div>
      <button type="submit" class="btn-login">Continue</button>
    </form>

    <div class="login-divider"><span>or</span></div>

    <a href="index.html" class="btn-create-account">Create a new account</a>

    <!-- ── Get Help ── -->
    <div class="help-section" id="helpSection">
      <button class="help-toggle" onclick="toggleHelp()" aria-expanded="false">
        Get help
        <span class="icon">&#9660;</span>
      </button>
      <div class="help-content">
        <div class="help-content-inner">
          <p><strong>Forgot your email or password?</strong></p>
          <p>If you don't remember your email, go to <a href="#">Account Recovery</a>. If you forgot your password, <a href="#">reset it here</a>.</p>
          <p style="margin-top:12px"><strong>Need more help?</strong></p>
          <p>Visit our <a href="#">Help Centre</a> or <a href="#faq">Contact Us</a>.</p>
        </div>
      </div>
    </div>
  </div>
</main>

<!-- ── Footer ── -->
<footer class="login-footer">
  <p>This page is protected by Google reCAPTCHA to ensure you're not a bot. <a href="#">Learn more.</a></p>
</footer>

<script>
(function(){
  /* ── Get Help toggle ── */
  window.toggleHelp = function(){
    var section = document.getElementById('helpSection');
    var btn = section.querySelector('.help-toggle');
    var isOpen = section.classList.contains('open');
    if (isOpen) {
      section.classList.remove('open');
      btn.setAttribute('aria-expanded','false');
    } else {
      section.classList.add('open');
      btn.setAttribute('aria-expanded','true');
    }
  };

  /* ── Login form handler ── */
  window.handleLogin = function(e){
    e.preventDefault();
    var form = e.target;
    var email = form.querySelector('#email');
    var password = form.querySelector('#password');
    var valid = true;

    if (!email.value.trim()) {
      email.setCustomValidity('Please enter your email or mobile number.');
      valid = false;
    } else {
      email.setCustomValidity('');
    }

    if (!password.value || password.value.length < 4) {
      password.setCustomValidity('Password must be at least 4 characters.');
      valid = false;
    } else {
      password.setCustomValidity('');
    }

    form.classList.add('submitted');

    if (valid) {
      alert('Sign-in successful! (This is a demo — no real authentication.)');
    }
    return false;
  };
})();
</script>

</body>
</html>
